/* CLEMOUNT Engineering Hub — beta front-end prototype. Data persists in this browser via localStorage. */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const store={get(k,d){try{return JSON.parse(localStorage.getItem('clemount_'+k))??d}catch{return d}},set(k,v){localStorage.setItem('clemount_'+k,JSON.stringify(v))}};
const names={inicio:'Visão geral',empresa:'Sobre & equipe',servicos:'Serviços e projetos',rack:'Rack Builder',energia:'Power & Energy',termica:'Thermal Analysis',hardware:'Hardware Analyzer',redes:'Network Designer',automacao:'Automation Lab',ia:'AI Lab',cloud:'Olimpo Cloud',virtualizacao:'Virtualization Lab',monitoramento:'Monitoring Center',seguranca:'Security Center',backup:'Backup & Recovery',cftv:'CFTV',arquitetura:'IT Architecture',bi:'Business Intelligence',projetos:'Project Management',documentacao:'Documentation Center',contato:'Contato'};
const descriptions={rack:'Planeje a ocupação física do rack, organize equipamentos e acompanhe espaço utilizado.',energia:'Estime a demanda elétrica, consumo de energia e custo operacional dos equipamentos.',termica:'Registre temperaturas, estime carga térmica e documente estratégias de refrigeração.',hardware:'Cadastre componentes e registre verificações de compatibilidade de hardware.',redes:'Desenhe a topologia física e lógica, organize endereçamento IP e portas de rede.',automacao:'Modele gatilhos, condições e ações para automatizar processos de TI.',ia:'Explore aplicações de inteligência artificial para diagnóstico e apoio técnico.',cloud:'Compare modelos de nuvem e planeje uma arquitetura híbrida.',virtualizacao:'Documente hosts, máquinas virtuais, recursos e serviços virtualizados.',monitoramento:'Acompanhe indicadores demonstrativos e registre métricas dos sistemas.',seguranca:'Organize controles de segurança, riscos e políticas de acesso.',backup:'Planeje rotinas de backup, retenção e recuperação de dados.',cftv:'Planeje câmeras, cobertura, gravação e armazenamento de videomonitoramento.',arquitetura:'Visualize as disciplinas e dependências que compõem uma arquitetura profissional de TI.',bi:'Transforme indicadores operacionais em informações para tomada de decisão.',projetos:'Organize tarefas, responsáveis, prazos e entregas do projeto.',documentacao:'Mantenha inventário, decisões técnicas, diagramas e registros do ambiente.'};
let page='inicio';let rack=store.get('rack',Array(16).fill(null));let devices=store.get('devices',[]);let tasks=store.get('tasks',[{title:'Levantar especificações dos quatro computadores',status:'todo',owner:'Hardware'},{title:'Desenhar topologia física e lógica',status:'doing',owner:'Redes'},{title:'Conferir dados de energia do nobreak',status:'todo',owner:'Energia'},{title:'Documentar inventário inicial',status:'done',owner:'Gestão'}]);let logs=store.get('logs',[]);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
function head(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">CLEMOUNT / ENGINEERING HUB</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function card(title,body,extra=''){return `<section class="card ${extra}"><div class="card-head"><h3>${title}</h3></div>${body}</section>`}
function metric(label,value,icon,foot='Indicador demonstrativo'){return `<div class="card"><div class="card-head"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric">${value}</div><div class="metric-foot">${foot}</div></div>`}
function field(label,id,placeholder='',type='text',value='',extra=''){return `<div class="field ${extra}"><label for="${id}">${label}</label><input id="${id}" type="${type}" placeholder="${placeholder}" value="${esc(value)}"></div>`}
function selectField(label,id,opts,value=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${opts.map(o=>`<option ${o[0]===value?'selected':''} value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></div>`}
function saveLog(message){logs.unshift({date:new Date().toLocaleString('pt-BR'),message});logs=logs.slice(0,50);store.set('logs',logs)}
function go(p){page=names[p]?p:'inicio';location.hash=page;render();$('#sidebar').classList.remove('open');}
function render(){let content=pages[page]?.()||pages.inicio();$('#pageContent').innerHTML=content;$('#crumbName').textContent=names[page];$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));bindPage();}
const pages={
inicio:()=>`${head('Infraestrutura inteligente. <span style="color:var(--purple)">Visão integrada.</span>','Bem-vindo ao ambiente de planejamento da CLEMOUNT. Centralize o projeto do rack, valide premissas e documente as decisões técnicas.','<button class="btn" data-go="rack">Abrir Rack Builder →</button>')}<section class="hero"><div class="hero-copy"><div class="eyebrow">TECHNOLOGY & ENGINEERING</div><h1>Seu projeto.<br>Uma infraestrutura <span style="color:#8e83ff">bem planejada.</span></h1><p>Da arquitetura física à operação: ferramentas para planejar, analisar e apresentar uma infraestrutura de TI organizada, segura e escalável.</p><div class="hero-actions"><button class="btn" data-go="rack">Começar planejamento →</button><button class="btn secondary" data-go="arquitetura">Conhecer arquitetura</button></div></div><img src="assets/server-rack-hero.png" alt="Rack de servidores ilustrativo"></section><div class="section-title">Painel do projeto</div><div class="grid grid-4">${metric('Equipamentos cadastrados',devices.length,'▣','Inventário local')}${metric('Posições ocupadas',rack.filter(Boolean).length+'/16','▤','Rack virtual de demonstração')}${metric('Tarefas concluídas',tasks.filter(t=>t.status==='done').length,'✓','Quadro de projeto')}${metric('Registros técnicos',logs.length,'⌁','Histórico deste navegador')}</div><div class="section-title">Acesso rápido às ferramentas</div><div class="grid grid-3">${[['rack','▤','Rack Builder','Monte a distribuição virtual dos equipamentos.'],['energia','ϟ','Power & Energy','Calcule demanda, consumo e custo estimado.'],['termica','♨','Thermal Analysis','Registre temperaturas e parâmetros térmicos.'],['redes','⌘','Network Designer','Planeje a rede física e lógica.'],['hardware','▣','Hardware Analyzer','Registre especificações e compatibilidade.'],['monitoramento','◉','Monitoring Center','Visualize métricas demonstrativas.']].map(x=>`<a href="#${x[0]}" data-go="${x[0]}" class="card quick-card"><div class="quick-icon">${x[1]}</div><div><b>${x[2]}</b><span>${x[3]}</span></div></a>`).join('')}</div><div class="section-title">Andamento e avisos</div><div class="grid grid-2">${card('Próximas atividades',`<div class="table-wrap"><table><thead><tr><th>Atividade</th><th>Responsável</th><th>Status</th></tr></thead><tbody>${tasks.slice(0,4).map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.owner)}</td><td><span class="pill ${t.status==='done'?'green':t.status==='doing'?'':'orange'}">${t.status==='done'?'Concluído':t.status==='doing'?'Em andamento':'A fazer'}</span></td></tr>`).join('')}</tbody></table></div>`)}${card('Atenção técnica',`<div class="notice warn">Os indicadores desta versão são demonstrativos ou calculados a partir dos dados que você informar. Não há conexão automática com o rack físico, sensores, câmeras ou equipamentos de rede.</div><p style="margin-top:12px">Cadastre os modelos e valores reais antes de usar os relatórios como documentação técnica.</p>`)}</div>`,
empresa:()=>`${head('Sobre a CLEMOUNT','Conheça a proposta, a equipe e a organização responsável pelo projeto.')}<div class="grid grid-2"><section class="card"><div class="eyebrow">NOSSA IDENTIDADE</div><h2 style="font:700 27px 'Space Grotesk'">Tecnologia com planejamento.</h2><p>A CLEMOUNT é uma empresa-projeto de tecnologia voltada ao planejamento, implantação e organização de ambientes de TI. Nossa proposta integra infraestrutura física, redes, sistemas, segurança, automação e gestão.</p><img src="assets/datacenter.png" style="width:100%;height:190px;object-fit:cover;border-radius:9px;margin-top:18px" alt="Ambiente de data center"></section>${card('Missão, visão e valores',`<h4>Missão</h4><p>Projetar soluções tecnológicas organizadas, seguras e adequadas às necessidades de cada ambiente.</p><h4>Visão</h4><p>Integrar infraestrutura e inovação para apoiar operações confiáveis e eficientes.</p><h4>Valores</h4><p>Responsabilidade técnica, colaboração, transparência, documentação e melhoria contínua.</p>`)}</div><div class="section-title">Equipe do projeto — seis integrantes</div><div class="grid grid-3">${[['CT','Gerência de TI','Arquitetura, integração e coordenação'],['HW','Hardware & Rack','Inventário e montagem física'],['NW','Redes','Topologia, endereçamento e conectividade'],['PW','Energia','Levantamento e documentação elétrica'],['CL','Sistemas & Cloud','Serviços, virtualização e automação'],['SC','Segurança & Operações','Segurança, CFTV e monitoramento']].map(m=>`<div class="card team-card"><div class="team-avatar">${m[0]}</div><b>${m[1]}</b><p style="margin-top:6px">${m[2]}</p></div>`).join('')}</div><div class="notice" style="margin-top:16px">Os nomes dos integrantes podem ser adicionados posteriormente. As funções acima são uma sugestão de divisão de responsabilidades, não uma atribuição definitiva.</div>`,
servicos:()=>`${head('Serviços e soluções','Áreas de atuação que compõem o portfólio institucional da CLEMOUNT.')}<div class="grid grid-3">${[['▤','Infraestrutura & servidores','Planejamento de racks, inventário, servidores, armazenamento e organização física.'],['⌘','Redes & conectividade','Topologias, endereçamento IP, segmentação e documentação de redes.'],['ϟ','Energia & ambiente','Levantamento de cargas, estimativas de consumo e planejamento térmico.'],['⬡','Segurança da informação','Controles de acesso, políticas, registros e boas práticas de proteção.'],['☁','Cloud & virtualização','Arquiteturas híbridas, máquinas virtuais e serviços em nuvem.'],['⤳','Automação & integração','Integração de sistemas, fluxos de trabalho e notificações.'],['▥','Dados & BI','Indicadores, relatórios e apoio à tomada de decisão.'],['✳','IA aplicada','Assistência técnica, classificação e análise de informações.'],['◉','Monitoramento & CFTV','Observabilidade de sistemas e planejamento de videomonitoramento.']].map(s=>`<div class="card"><div class="quick-icon">${s[0]}</div><h3 style="margin-top:12px">${s[1]}</h3><p>${s[2]}</p></div>`).join('')}</div><div class="section-title">Projetos em destaque</div><div class="grid grid-2"><div class="card"><img src="assets/server-rack-hero.png" alt="Rack de servidores" style="width:100%;height:170px;object-fit:cover;border-radius:8px"><h3 style="margin-top:13px">Infraestrutura com quatro computadores</h3><p>Projeto acadêmico de planejamento, montagem e validação de um ambiente de rack.</p></div><div class="card"><img src="assets/datacenter.png" alt="Data center" style="width:100%;height:170px;object-fit:cover;border-radius:8px"><h3 style="margin-top:13px">CLEMOUNT Engineering Hub</h3><p>Plataforma demonstrativa para consolidar inventário, cálculos, diagramas e documentação.</p></div></div>`,
rack:()=>{let used=rack.filter(Boolean).length;return `${head('Rack Builder','Monte uma representação 2D do rack, posicione equipamentos e acompanhe a ocupação.','<button class="btn secondary" data-action="rack-reset">Limpar rack</button><button class="btn" data-action="rack-export">Exportar configuração</button>')}<div class="notice" style="margin-bottom:15px">Protótipo 2D com 16 posições ilustrativas. A altura real em U e as dimensões devem ser configuradas conforme o rack e os equipamentos físicos escolhidos. Arraste um equipamento ou use o botão adicionar.</div><div class="rack-layout"><section class="card"><div class="card-head"><h3>Catálogo</h3></div><div class="equipment-list">${[['Servidor 1U','server'],['Servidor 2U','server'],['Switch','network'],['Roteador','router'],['Patch panel','cable'],['Nobreak / UPS','battery'],['Bandeja','layers'],['Organizador','align']].map(e=>`<div class="equip-item" draggable="true" data-equip="${e[0]}"><span>▣ ${e[0]}</span><button class="btn small" data-add-equip="${e[0]}">+</button></div>`).join('')}</div><p class="small muted" style="margin-top:13px">Clique em + para adicionar à próxima posição livre.</p></section><section class="card"><div class="card-head"><h3>Rack virtual</h3><span class="pill">${used}/16 posições</span></div><div class="rack-frame"><div class="rack-top"><span>CLEMOUNT / RACK-01</span><span>FRONT VIEW</span></div><div class="rack-slots">${rack.map((e,i)=>`<div class="rack-slot ${e?'filled':''}" data-slot="${i}">${e?`<span>▣ ${esc(e)} <small>· U${i+1}</small></span><span class="remove" data-remove-slot="${i}">×</span>`:`U${i+1} — livre`}</div>`).join('')}</div></div><div class="metric-label" style="text-align:center;margin-top:12px">Representação conceitual — não substitui desenho técnico cotado.</div></section><section class="card"><div class="card-head"><h3>Resumo & validação</h3></div><div class="metric">${Math.round(used/16*100)}%</div><div class="metric-label">Ocupação visual do modelo</div><div class="bar" style="margin:10px 0 17px"><span style="width:${used/16*100}%"></span></div><p><b>Equipamentos:</b> ${used}</p><p style="margin-top:8px"><b>Posições livres:</b> ${16-used}</p><div class="notice warn" style="margin-top:14px">A ocupação por blocos não valida peso, profundidade, trilhos, distribuição de massa, ventilação ou capacidade elétrica. Verifique os manuais e dados reais.</div></section></div>`},
energia:()=>`${head('Power & Energy','Calcule estimativas de demanda, consumo mensal e custo com base nos equipamentos cadastrados.')}<div class="grid grid-2"><section class="card"><h3>Adicionar carga</h3><p>Informe potência ativa estimada de cada equipamento em watts e quantidade.</p><form id="powerForm" class="form-grid" style="margin-top:15px">${field('Equipamento','pName','Ex.: Computador 1')}${field('Potência por unidade (W)','pWatts','Ex.: 250','number')}${field('Quantidade','pQty','1','number')}${field('Horas de uso por dia','pHours','8','number')}<div class="field full"><label for="pRate">Tarifa de energia (R$/kWh)</label><input id="pRate" type="number" step="0.01" placeholder="Ex.: 0,95"></div><div class="field full"><button class="btn">Adicionar ao cálculo</button></div></form></section><section class="card"><h3>Resumo energético</h3><div class="grid grid-2" style="margin-top:12px"><div><div class="metric" id="pTotal">0 W</div><span class="metric-label">Potência somada informada</span></div><div><div class="metric" id="pKwh">0 kWh</div><span class="metric-label">Consumo estimado / mês</span></div><div><div class="metric" id="pCost">R$ 0,00</div><span class="metric-label">Custo estimado / mês</span></div><div><div class="metric" id="pLoad">—</div><span class="metric-label">Carga cadastrada</span></div></div><div class="notice warn" style="margin-top:15px">Estimativa simplificada: potência × horas de uso × 30 dias. Não é dimensionamento de circuito, proteção, condutores ou autonomia de UPS.</div></section></div><div class="section-title">Inventário de cargas</div>${card('Equipamentos cadastrados',`<div class="table-wrap"><table id="powerTable"><thead><tr><th>Equipamento</th><th>Qtd.</th><th>W/un.</th><th>Horas/dia</th><th>kWh/mês</th><th></th></tr></thead><tbody id="powerRows"></tbody></table></div>`)}`,
termica:()=>`${head('Thermal Analysis','Registre temperaturas e parâmetros do ambiente para apoiar a avaliação térmica do rack.')}<div class="grid grid-2"><section class="card"><h3>Registrar medição</h3><form id="thermalForm" class="form-grid" style="margin-top:14px">${field('Ponto de medição','tPoint','Ex.: Entrada frontal')}${field('Temperatura (°C)','tTemp','Ex.: 24','number')}${selectField('Localização','tLocation',[['front','Frente / entrada'],['rear','Traseira / exaustão'],['room','Ambiente'],['rack','Interior do rack']])}<div class="field"><label for="tNote">Observações</label><input id="tNote" placeholder="Condição do ambiente"></div><div class="field full"><button class="btn">Salvar medição</button></div></form></section><section class="card"><h3>Conceitos para análise</h3><p>Compare temperaturas de entrada e saída, consulte os limites indicados pelos fabricantes e considere temperatura ambiente, carga térmica, fluxo de ar e obstruções.</p><div class="notice warn" style="margin-top:15px">Sem sensores e medições reais, não é possível afirmar que o rack está termicamente seguro. Este módulo registra dados informados e não executa CFD.</div></section></div><div class="section-title">Histórico de medições</div>${card('Leituras registradas',`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Ponto</th><th>Local</th><th>Temperatura</th><th>Observação</th></tr></thead><tbody id="thermalRows"></tbody></table></div>`)}`,
hardware:()=>`${head('Hardware Analyzer','Cadastre componentes e registre verificações de compatibilidade com evidências e observações.')}<div class="grid grid-2"><section class="card"><h3>Novo componente</h3><form id="hardwareForm" class="form-grid" style="margin-top:14px">${field('Nome do componente','hName','Ex.: Placa-mãe')}${selectField('Categoria','hType',[['CPU','Processador'],['MB','Placa-mãe'],['RAM','Memória RAM'],['GPU','GPU'],['PSU','Fonte'],['SSD','Armazenamento'],['NET','Rede'],['OTHER','Outro']])}${field('Modelo / especificação','hModel','Fabricante e modelo','text','','full')}${field('Interface / soquete','hInterface','Ex.: AM4, DDR4, PCIe')}${field('Observações','hNotes','Requisito ou evidência')}<div class="field full"><button class="btn">Cadastrar componente</button></div></form></section>${card('Matriz de verificação',`<p>Registre cada relação como verificada somente após consultar documentação oficial dos fabricantes.</p><div class="notice" style="margin-top:12px">CPU ↔ placa-mãe · RAM ↔ placa-mãe · SSD ↔ interface · fonte ↔ demanda · sistema operacional ↔ hardware.</div><p style="margin-top:12px">A plataforma não possui banco automático de compatibilidade de fabricantes nesta versão.</p>`)}</div><div class="section-title">Inventário de hardware</div>${card('Componentes',`<div class="table-wrap"><table><thead><tr><th>Componente</th><th>Categoria</th><th>Modelo</th><th>Interface</th><th>Notas</th></tr></thead><tbody id="hardwareRows"></tbody></table></div>`)}`,
redes:()=>`${head('Network Designer','Planeje a arquitetura física e lógica, endereçamento IPv4 e portas de conectividade.')}<div class="grid grid-2"><section class="card"><h3>Adicionar dispositivo</h3><form id="networkForm" class="form-grid" style="margin-top:14px">${field('Nome','nName','Ex.: PC-01')}${selectField('Tipo','nType',[['pc','Computador'],['switch','Switch'],['router','Roteador'],['server','Servidor'],['ap','Access point']])}${field('Endereço IPv4','nIP','Ex.: 192.168.1.10')}${field('VLAN (opcional)','nVlan','Ex.: 10')}${field('Portas necessárias','nPorts','1','number')}<div class="field full"><button class="btn">Adicionar dispositivo</button></div></form></section><section class="card"><h3>Validação lógica básica</h3><p>O sistema verifica formato IPv4 e duplicidade entre os endereços cadastrados. Máscara, gateway, VLAN e roteamento precisam ser planejados e conferidos separadamente.</p><div id="networkSummary" class="notice" style="margin-top:14px">Nenhum dispositivo cadastrado.</div></section></div><div class="section-title">Topologia — visão lógica</div>${card('Diagrama de dispositivos',`<div class="diagram"><div class="network-canvas" id="networkCanvas"><div class="node"><span class="node-icon">☁</span><b>Gateway / Roteador</b></div><div class="connector"></div><div class="node"><span class="node-icon">⌘</span><b>Switch principal</b></div><div class="connector"></div><div class="network-row" id="networkNodes"></div></div></div><p class="small muted" style="margin-top:10px">Diagrama conceitual. As ligações físicas devem ser documentadas e verificadas na montagem real.</p>`)}<div class="section-title">Inventário de rede</div>${card('Dispositivos',`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>IPv4</th><th>VLAN</th><th>Portas</th><th>Validação</th></tr></thead><tbody id="networkRows"></tbody></table></div>`)}`,
automacao:()=>`${head('Automation Lab','Modele processos com gatilhos, condições e ações. Os fluxos são protótipos documentais, não executam ações em sistemas externos.')}<div class="grid grid-2"><section class="card"><h3>Construtor de fluxo</h3><form id="automationForm" class="form-grid" style="margin-top:14px">${field('Nome do fluxo','aName','Ex.: Alerta de servidor')}${selectField('Gatilho','aTrigger',[['alert','Alerta de monitoramento'],['schedule','Agendamento'],['webhook','Webhook recebido'],['manual','Execução manual']])}${selectField('Condição','aCondition',[['offline','Serviço indisponível'],['threshold','Limite excedido'],['always','Sempre']])}${selectField('Ação','aAction',[['notify','Notificar responsável'],['ticket','Registrar ocorrência'],['log','Salvar em log'],['report','Gerar relatório']])}<div class="field full"><button class="btn">Adicionar etapa</button></div></form></section><section class="card"><h3>Fluxo de referência</h3><div class="notice">Evento → validação da condição → execução da ação → registro e notificação.</div><p style="margin-top:12px">Ferramentas como n8n, webhooks e APIs podem implementar fluxos reais após configuração de credenciais, permissões e testes.</p></section></div><div class="section-title">Fluxos cadastrados</div>${card('Biblioteca de automações',`<div id="automationRows"></div>`)}`,
ia:()=>`${head('AI Lab','Aplicações de inteligência artificial para apoiar diagnóstico, classificação e documentação técnica.')}<div class="grid grid-2"><section class="card"><div class="eyebrow">ASSISTENTE CONCEITUAL</div><h3>Consultor de infraestrutura</h3><p>Descreva uma situação e receba um roteiro de investigação baseado em boas práticas gerais. Esta demonstração usa respostas locais predefinidas, não um modelo de IA conectado.</p><form id="aiForm" style="margin-top:14px"><div class="field"><label for="aiQuestion">Qual situação deseja investigar?</label><textarea id="aiQuestion" placeholder="Ex.: servidor com uso elevado de memória..."></textarea></div><button class="btn" style="margin-top:10px">Analisar cenário</button></form><div id="aiAnswer" style="margin-top:14px"></div></section>${card('Casos de uso',`<ul style="font-size:11px;line-height:2;color:var(--muted);padding-left:17px"><li>Classificação de incidentes.</li><li>Resumo de logs e relatórios.</li><li>Detecção de tendências em métricas.</li><li>Apoio à documentação.</li><li>Assistente para inventário e procedimentos.</li></ul><div class="notice warn">Não insira senhas, dados pessoais ou informações confidenciais. Respostas automatizadas exigem validação humana.</div>`)}</div>`,
cloud:()=>`${head('Olimpo Cloud','Explore modelos de serviço e planeje uma arquitetura híbrida entre infraestrutura local e nuvem.')}<div class="grid grid-3">${[['IaaS','Infrastructure as a Service','Máquinas virtuais, redes, discos e recursos computacionais sob demanda.','Controle maior sobre sistemas e configuração.'],['PaaS','Platform as a Service','Ambientes gerenciados para desenvolver e executar aplicações.','Reduz a administração da plataforma.'],['SaaS','Software as a Service','Aplicações prontas disponibilizadas pela internet.','Consumo direto de software como serviço.']].map(c=>`<div class="cloud-card"><div class="eyebrow">${c[0]}</div><h4>${c[1]}</h4><p>${c[2]}</p><p style="margin-top:10px"><b>Característica:</b> ${c[3]}</p></div>`).join('')}</div><div class="section-title">Provedores e ecossistemas</div><div class="grid grid-4">${['AWS','Microsoft Azure','Google Cloud','Oracle Cloud','Cloudflare'].map(n=>`<div class="card"><h3>${n}</h3><p>Pesquisar serviços, regiões, preços, disponibilidade e requisitos diretamente na documentação oficial do provedor.</p></div>`).join('')}</div><div class="section-title">Planejador de arquitetura híbrida</div><section class="card"><form id="cloudForm" class="form-grid">${selectField('Banco de dados','dbPlace',[['local','Local / rack'],['cloud','Nuvem']])}${selectField('Aplicação web','appPlace',[['local','Local / rack'],['cloud','Nuvem']])}${selectField('Backup','backupPlace',[['local','Local'],['cloud','Nuvem'],['both','Híbrido']])}${selectField('Identidade e acesso','identityPlace',[['local','Local'],['cloud','Nuvem'],['both','Híbrido']])}<div class="field full"><button class="btn">Gerar resumo da arquitetura</button></div></form><div id="cloudResult"></div></section><div class="notice warn" style="margin-top:15px">A comparação comercial de provedores depende de região, configuração, tráfego, armazenamento, suporte e preços atualizados. Consulte as calculadoras oficiais antes de contratar.</div>`,
virtualizacao:()=>`${head('Virtualization Lab','Documente hosts físicos, hipervisores, máquinas virtuais e alocação de recursos.')}<div class="grid grid-2"><section class="card"><h3>Cadastrar máquina virtual</h3><form id="vmForm" class="form-grid" style="margin-top:14px">${field('Nome da VM','vmName','Ex.: VM-APP-01')}${selectField('Sistema operacional','vmOS',[['Linux','Linux'],['Windows Server','Windows Server'],['Windows','Windows'],['Outro','Outro']])}${field('vCPU','vmCpu','2','number')}${field('Memória RAM (GB)','vmRam','4','number')}${field('Disco (GB)','vmDisk','60','number')}<div class="field full"><button class="btn">Cadastrar VM</button></div></form></section>${card('Conceitos',`<p>Virtualização permite executar múltiplos ambientes isolados sobre um host físico, compartilhando recursos conforme limites e políticas definidos.</p><p style="margin-top:10px">Registre hipervisor, versão, CPU, memória, armazenamento, rede virtual, snapshots e política de backup.</p>`)}</div><div class="section-title">Inventário de máquinas virtuais</div>${card('Máquinas cadastradas',`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>SO</th><th>vCPU</th><th>RAM</th><th>Disco</th></tr></thead><tbody id="vmRows"></tbody></table></div>`)}`,
monitoramento:()=>`${head('Monitoring Center','Painel demonstrativo de observabilidade. Métricas simuladas não representam leitura do hardware real.','<button class="btn secondary" data-action="refresh-monitor">Atualizar demonstração</button>')}<div class="notice warn" style="margin-bottom:15px">MODO DEMONSTRAÇÃO — os valores abaixo são fictícios e servem somente para ilustrar uma interface de monitoramento. Para dados reais, integrar agentes e fontes como SNMP, Prometheus ou APIs autorizadas.</div><div class="grid grid-4">${metric('CPU','42%','⌁','Valor simulado')}${metric('Memória RAM','68%','▥','Valor simulado')}${metric('Tráfego','320 Mbps','⌘','Valor simulado')}${metric('Disponibilidade','99,9%','◷','Exemplo ilustrativo')}</div><div class="section-title">Indicadores operacionais</div><div class="grid grid-2">${card('Utilização de recursos',`<div class="chart">${[35,52,43,68,58,75,62,42].map((v,i)=>`<div class="col" style="height:${v}%"><small>${i+1}</small></div>`).join('')}</div><p style="margin-top:26px">Série fictícia de utilização ao longo de períodos ilustrativos.</p>`)}${card('Saúde dos serviços',`<div style="display:grid;gap:13px">${[['Servidor de arquivos','Operacional'],['Serviço web','Operacional'],['Banco de dados','Atenção'],['Switch principal','Operacional']].map(s=>`<div style="display:flex;justify-content:space-between;align-items:center"><span>${s[0]}</span><span class="pill ${s[1]==='Atenção'?'orange':'green'}">${s[1]} · simulado</span></div>`).join('')}</div>`)}</div>`,
seguranca:()=>`${head('Security Center','Central de controles, políticas e avaliação de riscos de segurança da informação.')}<div class="grid grid-2"><section class="card"><h3>Registrar controle</h3><form id="securityForm" class="form-grid" style="margin-top:14px">${field('Controle','sName','Ex.: MFA para administração')}${selectField('Categoria','sCategory',[['access','Controle de acesso'],['network','Rede'],['endpoint','Endpoint'],['backup','Backup'],['physical','Segurança física']])}${selectField('Status','sStatus',[['planned','Planejado'],['implemented','Implementado'],['review','Revisar']])}<div class="field full"><label for="sNote">Evidência / observação</label><textarea id="sNote" placeholder="Descreva como será verificado"></textarea></div><div class="field full"><button class="btn">Registrar controle</button></div></form></section>${card('Princípios de segurança',`<p><b>Confidencialidade:</b> acesso somente a quem possui autorização.</p><p><b>Integridade:</b> proteção contra alteração indevida.</p><p><b>Disponibilidade:</b> serviços acessíveis quando necessários.</p><p><b>Rastreabilidade:</b> logs e registros para auditoria.</p><div class="notice warn">A lista é um controle documental inicial, não uma auditoria ou certificação de segurança.</div>`)}</div><div class="section-title">Registro de controles</div>${card('Controles cadastrados',`<div class="table-wrap"><table><thead><tr><th>Controle</th><th>Categoria</th><th>Status</th><th>Observação</th></tr></thead><tbody id="securityRows"></tbody></table></div>`)}`,
backup:()=>`${head('Backup & Recovery','Planeje cópias, frequência, retenção e testes de restauração.')}<div class="grid grid-2"><section class="card"><h3>Nova política de backup</h3><form id="backupForm" class="form-grid" style="margin-top:14px">${field('Sistema / dados','bName','Ex.: Banco de dados')}${selectField('Frequência','bFreq',[['daily','Diário'],['weekly','Semanal'],['monthly','Mensal'],['continuous','Contínuo']])}${selectField('Destino','bDest',[['local','Armazenamento local'],['cloud','Nuvem'],['hybrid','Híbrido']])}${field('Retenção (dias)','bRetention','30','number')}<div class="field full"><button class="btn">Salvar política</button></div></form></section>${card('Estratégia de recuperação',`<p>Documente RPO (perda máxima de dados aceitável) e RTO (tempo desejado para recuperação) com base nos requisitos do negócio.</p><p style="margin-top:10px">Mantenha cópias separadas, controle de acesso e testes periódicos de restauração. Um backup só é confiável quando a recuperação foi testada.</p>`)}</div><div class="section-title">Políticas cadastradas</div>${card('Plano de backup',`<div class="table-wrap"><table><thead><tr><th>Sistema</th><th>Frequência</th><th>Destino</th><th>Retenção</th></tr></thead><tbody id="backupRows"></tbody></table></div>`)}`,
cftv:()=>`${head('CFTV & Monitoramento físico','Planeje câmeras IP, cobertura, gravação e armazenamento de vídeo.')}<div class="grid grid-2"><section class="card"><h3>Cadastrar câmera</h3><form id="cctvForm" class="form-grid" style="margin-top:14px">${field('Identificação','cName','Ex.: CAM-01')}${selectField('Tipo','cType',[['dome','Dome'],['bullet','Bullet'],['ptz','PTZ'],['other','Outro']])}${field('Local de instalação','cLocation','Ex.: Entrada do laboratório')}${field('Resolução','cResolution','Ex.: 1080p')}${field('Retenção desejada (dias)','cDays','15','number')}<div class="field full"><button class="btn">Cadastrar câmera</button></div></form></section>${card('Planejamento de armazenamento',`<p>O armazenamento depende de quantidade de câmeras, resolução, codec, taxa de quadros, bitrate, gravação contínua ou por evento e retenção.</p><div class="notice warn">A estimativa exige bitrate real por câmera. Não use apenas a resolução para definir capacidade de armazenamento.</div><p style="margin-top:10px">Considere privacidade, sinalização, controle de acesso às gravações e legislação aplicável.</p>`)}</div><div class="section-title">Inventário de CFTV</div>${card('Câmeras planejadas',`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Tipo</th><th>Local</th><th>Resolução</th><th>Retenção</th></tr></thead><tbody id="cctvRows"></tbody></table></div>`)}`,
arquitetura:()=>`${head('IT Architecture','A arquitetura profissional de TI integra tecnologia, pessoas, processos, segurança e objetivos de negócio.')}<div class="card" style="background:linear-gradient(110deg,#11101d,#17158e);color:white"><div class="eyebrow" style="color:#b9b2ff">VISÃO SISTÊMICA</div><h2 style="font:700 26px 'Space Grotesk';margin:10px 0">Da necessidade do negócio à operação tecnológica</h2><p style="color:#ddd">O profissional de TI traduz requisitos em uma arquitetura coerente, documentada, segura e sustentável.</p></div><div class="section-title">Domínios da arquitetura</div><div class="grid grid-4">${[['▤','Infraestrutura','Servidores, racks, armazenamento e endpoints.'],['⌘','Redes','Conectividade, IP, VLAN, roteamento e DNS.'],['⬡','Segurança','Identidade, acesso, proteção e auditoria.'],['☁','Cloud','Serviços, nuvem híbrida e escalabilidade.'],['▣','Sistemas','Sistemas operacionais, aplicações e serviços.'],['▥','Dados & BI','Banco de dados, indicadores e relatórios.'],['⤳','Automação','Integração, orquestração e processos.'],['◉','Operações','Monitoramento, suporte e continuidade.']].map(x=>`<div class="card"><div class="quick-icon">${x[0]}</div><h3 style="margin-top:12px">${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><div class="section-title">Ciclo de trabalho do profissional de TI</div><div class="grid grid-4">${['1. Levantamento de requisitos','2. Análise do ambiente','3. Planejamento e arquitetura','4. Seleção de tecnologias','5. Dimensionamento','6. Implementação','7. Testes e validação','8. Operação e melhoria contínua'].map((s,i)=>`<div class="card"><span class="pill">ETAPA ${i+1}</span><h3 style="margin-top:12px">${s}</h3></div>`).join('')}</div><div class="section-title">Dependências do projeto de rack</div><div class="diagram"><div class="network-canvas"><div class="node"><b>Gestão e arquitetura de TI</b></div><div class="connector"></div><div class="network-row">${['Infraestrutura','Redes','Energia','Sistemas','Segurança','Documentação'].map(n=>`<span class="node"><b>${n}</b></span>`).join('')}</div><div class="connector"></div><div class="node"><b>Ambiente integrado — quatro computadores + rack</b></div></div></div><div class="notice" style="margin-top:14px">O gerente de TI integra as áreas, acompanha riscos, valida requisitos, organiza responsabilidades e garante que documentação e implementação permaneçam coerentes.</div>`,
bi:()=>`${head('Business Intelligence','Acompanhe indicadores do projeto e transforme registros em informações gerenciais.')}<div class="grid grid-4">${metric('Tarefas totais',tasks.length,'☷','Quadro local')}${metric('Concluídas',tasks.filter(t=>t.status==='done').length,'✓','Quadro local')}${metric('Equipamentos',devices.length,'▣','Inventário local')}${metric('Registros',logs.length,'▥','Histórico local')}</div><div class="section-title">Distribuição de tarefas</div><div class="grid grid-2">${card('Status das atividades',`<div style="display:grid;gap:13px">${[['Concluídas',tasks.filter(t=>t.status==='done').length,'#16a36a'],['Em andamento',tasks.filter(t=>t.status==='doing').length,'#422efd'],['A fazer',tasks.filter(t=>t.status==='todo').length,'#e5a23c']].map(x=>`<div><div style="display:flex;justify-content:space-between;margin-bottom:5px;font-size:10px"><b>${x[0]}</b><span>${x[1]}</span></div><div class="bar"><span style="width:${tasks.length?x[1]/tasks.length*100:0}%;background:${x[2]}"></span></div></div>`).join('')}</div>`)}${card('Indicadores e interpretação',`<p>Use os dados cadastrados para acompanhar andamento, ocupação do rack, consumo estimado e pendências de validação.</p><div class="notice warn" style="margin-top:12px">Os indicadores são calculados com dados locais do protótipo. Não representam telemetria real nem desempenho de produção.</div>`)}</div>`,
projetos:()=>`${head('Project Management','Gerencie atividades, responsáveis e entregas do projeto acadêmico.','<button class="btn secondary" data-action="task-export">Exportar tarefas</button>')}<section class="card"><h3>Adicionar tarefa</h3><form id="taskForm" class="form-grid" style="margin-top:14px">${field('Descrição','taskTitle','Ex.: Testar conectividade dos quatro computadores')}${field('Responsável / área','taskOwner','Ex.: Redes')}${selectField('Status','taskStatus',[['todo','A fazer'],['doing','Em andamento'],['done','Concluído']])}<div class="field"><label for="taskDue">Prazo</label><input id="taskDue" type="date"></div><div class="field full"><button class="btn">Adicionar tarefa</button></div></form></section><div class="section-title">Quadro de atividades</div><div class="kanban" id="kanban"></div>`,
documentacao:()=>`${head('Documentation Center','Centralize especificações, decisões, inventário e registros técnicos do ambiente.','<button class="btn secondary" data-action="export-all">Exportar dados JSON</button>')}<div class="grid grid-2"><section class="card"><h3>Novo registro técnico</h3><form id="docForm" style="margin-top:14px"><div class="field"><label for="docTitle">Título</label><input id="docTitle" placeholder="Ex.: Endereçamento IPv4"></div><div class="field" style="margin-top:12px"><label for="docCategory">Categoria</label><select id="docCategory"><option>Infraestrutura</option><option>Redes</option><option>Energia</option><option>Segurança</option><option>Sistemas</option><option>Decisão técnica</option></select></div><div class="field" style="margin-top:12px"><label for="docBody">Conteúdo</label><textarea id="docBody" placeholder="Registre especificações, evidências, decisões e pendências..."></textarea></div><button class="btn" style="margin-top:12px">Salvar documentação</button></form></section>${card('Boas práticas documentais',`<ul style="font-size:11px;line-height:2;color:var(--muted);padding-left:17px"><li>Registrar fabricante, modelo e número de patrimônio.</li><li>Documentar versões, endereços e dependências.</li><li>Identificar autor e data das alterações.</li><li>Anexar evidências e fontes técnicas.</li><li>Manter cópias de segurança da documentação.</li></ul>`)}</div><div class="section-title">Documentos registrados</div><div id="docsList" class="grid grid-2"></div><div class="section-title">Histórico de atividades</div>${card('Log local',`<div id="logsList"></div>`)}`,
contato:()=>`${head('Entre em contato','Apresente uma necessidade, solicite informações ou conheça as soluções da CLEMOUNT.')}<div class="grid grid-2"><section class="card"><h3>Envie uma mensagem</h3><form id="contactForm" style="margin-top:14px"><div class="form-grid">${field('Nome','contactName','Seu nome')}${field('E-mail','contactEmail','seu@email.com','email')}${selectField('Assunto','contactSubject',[['project','Projeto de infraestrutura'],['network','Redes e conectividade'],['automation','Automação e sistemas'],['other','Outro']])}<div class="field full"><label for="contactMessage">Mensagem</label><textarea id="contactMessage" placeholder="Como podemos ajudar?"></textarea></div></div><button class="btn" style="margin-top:13px">Preparar mensagem</button></form><div class="notice" style="margin-top:12px">Protótipo: o formulário prepara uma mensagem no seu aplicativo de e-mail. Configure o endereço institucional antes da publicação.</div></section>${card('CLEMOUNT Technology & Engineering',`<h3>Infraestrutura · Inovação · Performance</h3><p>Empresa-projeto de tecnologia com foco em planejamento e integração de infraestrutura de TI.</p><p style="margin-top:14px">E-mail: configurar endereço institucional</p><p>Localização: informar dados da empresa</p><p>Atendimento: sob consulta</p>`)}</div>`
};
function read(key,def=[]){return store.get(key,def)}function rowEmpty(cols,msg='Nenhum registro cadastrado.'){return `<tr><td colspan="${cols}" class="empty">${msg}</td></tr>`}
function renderPower(){let rows=read('power',[]);let total=rows.reduce((a,x)=>a+x.w*x.q,0),kwh=rows.reduce((a,x)=>a+x.w*x.q*x.h*30/1000,0),rate=Number($('#pRate')?.value||0);$('#pTotal').textContent=total.toLocaleString('pt-BR')+' W';$('#pKwh').textContent=kwh.toFixed(1)+' kWh';$('#pCost').textContent=(kwh*rate).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});$('#pLoad').textContent=rows.length+' itens';$('#powerRows').innerHTML=rows.length?rows.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${x.q}</td><td>${x.w}</td><td>${x.h}</td><td>${(x.w*x.q*x.h*30/1000).toFixed(1)}</td><td><button class="btn secondary small" data-delete="power:${i}">Remover</button></td></tr>`).join(''):rowEmpty(6)}
function renderTables(){let map={thermal:['thermalRows',5,x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.point)}</td><td>${esc(x.loc)}</td><td>${x.temp} °C</td><td>${esc(x.note)}</td></tr>`],hardware:['hardwareRows',5,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${esc(x.model)}</td><td>${esc(x.intf)}</td><td>${esc(x.notes)}</td></tr>`],network:['networkRows',6,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${esc(x.ip||'—')}</td><td>${esc(x.vlan||'—')}</td><td>${x.ports}</td><td><span class="pill ${x.valid?'green':'orange'}">${x.valid?'Formato válido':'Verificar IP'}</span></td></tr>`],backup:['backupRows',4,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.freq)}</td><td>${esc(x.dest)}</td><td>${x.ret} dias</td></tr>`],cctv:['cctvRows',5,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${esc(x.loc)}</td><td>${esc(x.res)}</td><td>${x.days} dias</td></tr>`],security:['securityRows',4,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.cat)}</td><td>${esc(x.status)}</td><td>${esc(x.note)}</td></tr>`],vm:['vmRows',5,x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.os)}</td><td>${x.cpu}</td><td>${x.ram} GB</td><td>${x.disk} GB</td></tr>`]};Object.values(map).forEach(([id,n,fn])=>{let el=$('#'+id);if(el){let key=Object.keys(map).find(k=>map[k][0]===id);let arr=read(key,[]);el.innerHTML=arr.length?arr.map(fn).join(''):rowEmpty(n)}});let net=$('#networkNodes');if(net){let arr=read('network',[]);net.innerHTML=arr.map(x=>`<div class="node"><span class="node-icon">${x.type==='Computador'?'▣':x.type==='Switch'?'⌘':'◈'}</span><b>${esc(x.name)}</b><small>${esc(x.ip)}</small></div>`).join('')||'<span class="muted small">Adicione dispositivos para visualizar.</span>';$('#networkSummary').textContent=arr.length?`${arr.length} dispositivos cadastrados. ${arr.filter(x=>x.valid).length} endereços IPv4 com formato válido. Confirme máscara, gateway, VLAN e conectividade separadamente.`:'Nenhum dispositivo cadastrado.'}}
function renderKanban(){let el=$('#kanban');if(!el)return;el.innerHTML=[['todo','A fazer'],['doing','Em andamento'],['done','Concluído']].map(([key,title])=>`<div class="kanban-col"><h4>${title} · ${tasks.filter(t=>t.status===key).length}</h4>${tasks.map((t,i)=>({...t,i})).filter(t=>t.status===key).map(t=>`<div class="task"><b>${esc(t.title)}</b><small>${esc(t.owner)} ${t.due?'· '+esc(t.due):''}</small><div style="display:flex;gap:5px;margin-top:8px"><select data-task-status="${t.i}" style="font-size:9px;max-width:115px;border:1px solid #ddd;border-radius:5px;padding:4px"><option value="todo" ${key==='todo'?'selected':''}>A fazer</option><option value="doing" ${key==='doing'?'selected':''}>Em andamento</option><option value="done" ${key==='done'?'selected':''}>Concluído</option></select><button class="btn secondary small" data-delete="task:${t.i}">×</button></div></div>`).join('')}</div>`).join('')}
function bindPage(){if(page==='rack'){$$('[data-add-equip]').forEach(b=>b.onclick=()=>addRack(b.dataset.addEquip));$$('[data-remove-slot]').forEach(b=>b.onclick=()=>{rack[+b.dataset.removeSlot]=null;store.set('rack',rack);render()});$$('[data-equip]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.equip)});$$('[data-slot]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();let i=+el.dataset.slot;if(rack[i])return toast('Essa posição já está ocupada.');rack[i]=e.dataTransfer.getData('text/plain');store.set('rack',rack);render()}})}
if(page==='energia'){renderPower();$('#pRate').addEventListener('input',renderPower);$('#powerForm').onsubmit=e=>{e.preventDefault();let name=$('#pName').value.trim(),w=+$('#pWatts').value,q=+$('#pQty').value,h=+$('#pHours').value;if(!name||w<=0||q<=0||h<0||h>24)return toast('Confira os dados informados.');let a=read('power',[]);a.push({name,w,q,h});store.set('power',a);saveLog('Carga adicionada: '+name);render()}}
if(page==='termica'){$('#thermalForm').onsubmit=e=>{e.preventDefault();let a=read('thermal',[]);a.push({date:new Date().toLocaleString('pt-BR'),point:$('#tPoint').value, temp:+$('#tTemp').value,loc:$('#tLocation').selectedOptions[0].text,note:$('#tNote').value});store.set('thermal',a);saveLog('Medição térmica registrada');render()};renderTables()}
if(page==='hardware'){$('#hardwareForm').onsubmit=e=>{e.preventDefault();let a=read('hardware',[]);a.push({name:$('#hName').value,type:$('#hType').selectedOptions[0].text,model:$('#hModel').value,intf:$('#hInterface').value,notes:$('#hNotes').value});store.set('hardware',a);saveLog('Componente cadastrado');render()};renderTables()}
if(page==='redes'){$('#networkForm').onsubmit=e=>{e.preventDefault();let ip=$('#nIP').value.trim(),valid=/^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/.test(ip),a=read('network',[]);if(ip&&a.some(x=>x.ip===ip))return toast('Endereço IP duplicado no inventário.');a.push({name:$('#nName').value,type:$('#nType').selectedOptions[0].text,ip,vlan:$('#nVlan').value,ports:+$('#nPorts').value||1,valid});store.set('network',a);saveLog('Dispositivo de rede cadastrado');render()};renderTables()}
if(page==='automacao'){$('#automationForm').onsubmit=e=>{e.preventDefault();let a=read('automation',[]);a.push({name:$('#aName').value,trigger:$('#aTrigger').selectedOptions[0].text,condition:$('#aCondition').selectedOptions[0].text,action:$('#aAction').selectedOptions[0].text});store.set('automation',a);render()};let a=read('automation',[]);$('#automationRows').innerHTML=a.map(x=>`<div class="notice" style="margin:7px 0"><b>${esc(x.name)}</b><br>Quando: ${esc(x.trigger)} → Se: ${esc(x.condition)} → Então: ${esc(x.action)}</div>`).join('')||'<div class="empty">Nenhum fluxo cadastrado.</div>'}
if(page==='ia')$('#aiForm').onsubmit=e=>{e.preventDefault();let q=$('#aiQuestion').value.toLowerCase(),tips=q.includes('mem')?['Verifique o consumo por processo e serviço.','Compare a memória utilizada com a capacidade instalada.','Consulte logs e eventos recentes.','Avalie vazamentos, cache e necessidade de otimização.']:q.includes('rede')||q.includes('conex')?['Verifique link físico, LEDs e cabeamento.','Confira endereço IP, máscara, gateway e DNS.','Teste conectividade por etapas.','Consulte logs do switch e roteador.']:q.includes('temper')||q.includes('calor')?['Registre temperatura ambiente, entrada e exaustão.','Verifique obstruções e fluxo de ar.','Consulte os limites publicados pelo fabricante.','Revise carga térmica e condições do ambiente.']:['Descreva o sintoma, o horário de início e o escopo afetado.','Colete métricas, logs e mensagens de erro relevantes.','Verifique alterações recentes e dependências.','Teste uma hipótese por vez e documente o resultado.'];$('#aiAnswer').innerHTML=`<div class="notice"><b>Roteiro inicial de investigação</b><ol>${tips.map(t=>`<li>${t}</li>`).join('')}</ol><small>Resposta demonstrativa baseada em regras locais. Valide com documentação e equipe técnica.</small></div>`}
if(page==='cloud')$('#cloudForm').onsubmit=e=>{e.preventDefault();let vals=['dbPlace','appPlace','backupPlace','identityPlace'].map(id=>$('#'+id).selectedOptions[0].text);$('#cloudResult').innerHTML=`<div class="notice good" style="margin-top:13px"><b>Resumo da arquitetura planejada</b><br>Banco de dados: ${vals[0]}<br>Aplicação: ${vals[1]}<br>Backup: ${vals[2]}<br>Identidade: ${vals[3]}<br><small>Validar conectividade, segurança, latência, custo e recuperação.</small></div>`}
if(page==='virtualizacao'){$('#vmForm').onsubmit=e=>{e.preventDefault();let a=read('vm',[]);a.push({name:$('#vmName').value,os:$('#vmOS').value,cpu:+$('#vmCpu').value,ram:+$('#vmRam').value,disk:+$('#vmDisk').value});store.set('vm',a);render()};renderTables()}
if(page==='monitoramento'){$('[data-action="refresh-monitor"]')?.addEventListener('click',()=>toast('Demonstração atualizada. Valores continuam simulados.'))}
if(page==='seguranca'){$('#securityForm').onsubmit=e=>{e.preventDefault();let a=read('security',[]);a.push({name:$('#sName').value,cat:$('#sCategory').selectedOptions[0].text,status:$('#sStatus').selectedOptions[0].text,note:$('#sNote').value});store.set('security',a);render()};renderTables()}
if(page==='backup'){$('#backupForm').onsubmit=e=>{e.preventDefault();let a=read('backup',[]);a.push({name:$('#bName').value,freq:$('#bFreq').selectedOptions[0].text,dest:$('#bDest').selectedOptions[0].text,ret:+$('#bRetention').value});store.set('backup',a);render()};renderTables()}
if(page==='cftv'){$('#cctvForm').onsubmit=e=>{e.preventDefault();let a=read('cctv',[]);a.push({name:$('#cName').value,type:$('#cType').selectedOptions[0].text,loc:$('#cLocation').value,res:$('#cResolution').value,days:+$('#cDays').value});store.set('cctv',a);render()};renderTables()}
if(page==='projetos'){$('#taskForm').onsubmit=e=>{e.preventDefault();tasks.push({title:$('#taskTitle').value,owner:$('#taskOwner').value,status:$('#taskStatus').value,due:$('#taskDue').value});store.set('tasks',tasks);saveLog('Tarefa adicionada');render()};renderKanban();$$('[data-task-status]').forEach(s=>s.onchange=()=>{tasks[+s.dataset.taskStatus].status=s.value;store.set('tasks',tasks);render()})}
if(page==='documentacao'){$('#docForm').onsubmit=e=>{e.preventDefault();let a=read('docs',[]);a.unshift({title:$('#docTitle').value,cat:$('#docCategory').value,body:$('#docBody').value,date:new Date().toLocaleString('pt-BR')});store.set('docs',a);saveLog('Documento técnico criado');render()};let docs=read('docs',[]);$('#docsList').innerHTML=docs.map(d=>`<div class="card"><span class="pill">${esc(d.cat)}</span><h3 style="margin-top:10px">${esc(d.title)}</h3><p>${esc(d.body)}</p><div class="metric-foot">${esc(d.date)}</div></div>`).join('')||'<div class="empty">Nenhum documento registrado.</div>';$('#logsList').innerHTML=logs.map(l=>`<div style="padding:9px 0;border-bottom:1px solid var(--line);font-size:10px"><b>${esc(l.message)}</b><span class="muted" style="float:right">${esc(l.date)}</span></div>`).join('')||'<div class="empty">Sem atividades registradas.</div>'}
if(page==='contato')$('#contactForm').onsubmit=e=>{e.preventDefault();let subject=encodeURIComponent('Contato CLEMOUNT — '+$('#contactSubject').selectedOptions[0].text),body=encodeURIComponent(`Nome: ${$('#contactName').value}\nE-mail: ${$('#contactEmail').value}\n\n${$('#contactMessage').value}`);toast('Abrindo aplicativo de e-mail. Configure o destinatário no código.');location.href=`mailto:contato@clemount.com?subject=${subject}&body=${body}`}
}
function addRack(name){let i=rack.findIndex(x=>!x);if(i<0)return toast('Rack virtual sem posições livres.');rack[i]=name;store.set('rack',rack);saveLog('Equipamento adicionado ao rack: '+name);render()}
function exportFile(name,data,type='application/json'){let blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);toast('Arquivo exportado.')}
function bindGlobal(){document.addEventListener('click',e=>{let g=e.target.closest('[data-go]');if(g){e.preventDefault();go(g.dataset.go);return}let act=e.target.closest('[data-action]')?.dataset.action;if(act==='rack-reset'){if(confirm('Limpar todos os equipamentos do rack virtual?')){rack=Array(16).fill(null);store.set('rack',rack);render()}}if(act==='rack-export')exportFile('clemount-rack.json',{rack,exportadoEm:new Date().toISOString()});if(act==='export-all')exportFile('clemount-projeto.json',Object.fromEntries(['rack','devices','power','thermal','hardware','network','automation','vm','security','backup','cctv','tasks','docs','logs'].map(k=>[k,store.get(k,[])])));if(act==='task-export')exportFile('clemount-tarefas.json',tasks);let del=e.target.closest('[data-delete]')?.dataset.delete;if(del){let [key,idx]=del.split(':');if(key==='task'){tasks.splice(+idx,1);store.set('tasks',tasks)}else{let a=read(key,[]);a.splice(+idx,1);store.set(key,a)}render()}});$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeToggle').onclick=()=>{document.body.classList.toggle('dark-mode');store.set('dark',document.body.classList.contains('dark-mode'))};$('#modalClose').onclick=()=>$('#modal').close();if(store.get('dark',false))document.body.classList.add('dark-mode');}
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(names[p]){page=p;render()}});bindGlobal();page=names[location.hash.slice(1)]?location.hash.slice(1):'inicio';render();
